function variants(p){const sizes=p.sizes?.length?p.sizes:[{name:'Regular',price:p.onSale?p.salePrice:p.price}],extras=(p.extras||[]).slice(0,5),out=[];for(let size=0;size<sizes.length;size++)for(let mask=0;mask<2**extras.length;mask++){const chosen=extras.filter((_,i)=>mask&(1<<i));out.push({label:[sizes[size].name,...chosen.map(e=>e.name)].join(' + '),price:Number(sizes[size].price)+chosen.reduce((a,e)=>a+Number(e.price),0),stock:p.stock||100,attributes:{Size:sizes[size].name,Extras:chosen.map(e=>e.name).join(', ')||'None'},size,mask});}return out;}
function productItems(d){return d.items.map(p=>({id:p.id,name:p.name,description:p.description,price:p.price,active:p.active,images:p.images,variants:variants(p),trackStock:false,categories:[d.categories.find(c=>c.id===p.category)?.name||p.category],seoSlug:p.id}));}
function txt(d,path,o){return '<span data-key="'+esc(path)+'"'+(o.edit?' contenteditable="true" spellcheck="false"':'')+'>'+esc(get(d,path)).replace(/\n/g,'<br>')+'</span>';}
function img(src,alt,key){return '<img src="'+esc(safe(src))+'" alt="'+esc(alt)+'"'+(key?' data-media="'+esc(key)+'"':'')+' loading="lazy">';}
function link(label,page,cls=''){return '<a href="#'+esc(page)+'" class="'+cls+'">'+label+'</a>';}
function card(d,p,o){const i=d.items.indexOf(p);return '<article class="food-card" data-movable="item-'+esc(p.id)+'">'+link(img(p.images[0],p.name,'items.'+i+'.images.0'),'item/'+p.id)+'<h3>'+link(txt(d,'items.'+i+'.name',o),'item/'+p.id)+'</h3><p>'+txt(d,'items.'+i+'.description',o)+'</p><div class="food-card-bottom"><b>'+money(p.onSale?p.salePrice:p.price)+'</b><button data-item="'+esc(p.id)+'">Choose options +</button></div></article>';}
function itemGrid(d,items,o){return '<div class="food-grid">'+items.map(p=>card(d,p,o)).join('')+'</div>';}
function header(d,o){const visible=d.menu.filter(m=>m.visible!==false);return (d.announcementEnabled?'<div class="food-announcement">'+txt(d,'announcement',o)+'</div>':'')+'<header class="food-header"><a href="#home" class="food-brand">'+(d.logo?img(d.logo,d.brand,'logo'):txt(d,'brand',o)+'<small>'+txt(d,'tagline',o)+'</small>')+'</a><nav>'+visible.slice(0,5).map(m=>link(esc(m.title),m.id)).join('')+(visible.length>5?'<details class="food-overflow"><summary>☰</summary><div>'+visible.slice(5).map(m=>link(esc(m.title),m.id)).join('')+'</div></details>':'')+'</nav><a href="#cart" class="food-bag">Bag (<span data-cart-count>0</span>)</a></header>';}
function legacyFooter(d,o){return '<footer class="food-footer"><div><h2>'+txt(d,'brand',o)+'</h2><p>'+txt(d,'footer',o)+'</p></div><div><h3>Learn & connect</h3>'+link('Learning resources','menu')+link('Book coaching','reservations')+link('Catering','catering')+link('My orders','orders')+'</div><div><h3>Here to help</h3>'+link('Contact us','contact')+link('FAQs','faq')+link('Delivery','delivery')+link('Refunds','refunds')+link('Privacy & terms','privacy')+'</div><small>© '+new Date().getFullYear()+' '+esc(d.brand)+' · Hosted by SGC Network</small></footer>';}

function projectCard(d,p,o){const i=d.projects.indexOf(p);return '<article class="creative-project">'+link(img(p.image,p.name,'projects.'+i+'.image'),'project/'+p.id)+'<small>'+esc(p.category)+'</small><h3>'+link(txt(d,'projects.'+i+'.name',o),'project/'+p.id)+'</h3><p>'+txt(d,'projects.'+i+'.description',o)+'</p></article>'}
function portfolio(d,o,category=''){return '<section class="food-section"><h1 class="food-headline">Selected work</h1><div class="food-filters">'+[['','All'],['photography','Photography'],['art','Fine Art'],['design','Design']].map(([id,name])=>link(name,id?'portfolio/'+id:'portfolio',category===id?'active':'')).join('')+'</div><div class="food-grid">'+d.projects.filter(p=>p.visible&&(!category||p.category===category)).map(p=>projectCard(d,p,o)).join('')+'</div></section>'}
function services(d,o){return '<section class="food-section"><h2 class="food-headline">Creative services for every story</h2><div class="food-grid">'+d.services.map((s,i)=>'<article class="food-box"><h3>'+txt(d,'services.'+i+'.name',o)+'</h3><p>'+txt(d,'services.'+i+'.description',o)+'</p><p>From '+money(s.price)+'</p>'+link('Discuss your project','commissions','food-button secondary')+'</article>').join('')+'</div></section>'}

function homeSection(d,id,o){switch(id){case 'benefits':return '<div class="edu-benefits"><span>✦ Practical learning for real life</span><span>✦ Expert coaching and support</span><span>✦ A community to help you grow</span></div>';case 'courses':return courseCatalogue(d,o,'',true);case 'coaching':return coachingPage(d,o);case 'memberships':return membershipsPage(d,o);case 'testimonials':return educationPage(d,'testimonials',o,{});case 'portfolio':return portfolio(d,o);case 'services':return services(d,o);case 'hero':return '<section class="food-hero" data-section="hero"><div><small class="food-eyebrow">'+txt(d,'tagline',o)+'</small><h1>'+txt(d,'heroTitle',o)+'</h1><p>'+txt(d,'heroSubtitle',o)+'</p><div class="food-buttons">'+link(txt(d,'heroButton',o),d.heroTarget,'food-button')+link(txt(d,'heroSecondButton',o),d.heroSecondTarget,'food-button secondary')+'</div></div>'+img(d.heroImage,'Your learning and coaching partner','heroImage')+'</section>';case 'categories':return '<section class="food-section" data-section="categories"><div class="food-section-head"><h2>'+txt(d,'categoriesTitle',o)+'</h2>'+link('View our collection →','menu')+'</div><div class="food-categories">'+d.categories.filter(c=>c.visible!==false).map(c=>link(img(c.image,c.name,'categories.'+d.categories.indexOf(c)+'.image')+'<span>'+esc(c.name)+'</span>','category/'+c.id)).join('')+'</div></section>';case 'featured':return '<section class="food-section" data-section="featured"><div class="food-section-head"><h2>'+txt(d,'featuredTitle',o)+'</h2>'+link('View collection →','menu')+'</div>'+itemGrid(d,d.items.filter(p=>p.active&&p.featured).slice(0,6),o)+'</section>';case 'specials':return '<section class="food-promo" data-section="specials"><div><small class="food-eyebrow">CREATIVE SERVICES</small><h2>'+txt(d,'specialTitle',o)+'</h2><p>'+txt(d,'specialText',o)+'</p><p class="food-price">'+money(d.specialPrice)+'</p>'+link('Explore the menu →','menu','food-button')+'</div>'+img(d.specialImage,'Our latest special','specialImage')+'</section>';case 'about':return '<section class="food-section food-story" data-section="about">'+img(d.aboutImage,'The artist studio','aboutImage')+'<div><small class="food-eyebrow">OUR STORY</small><h2>'+txt(d,'aboutTitle',o)+'</h2><p>'+txt(d,'about',o)+'</p>'+link('Read our story →','about','food-button secondary')+'</div></section>';case 'gallery':return '<section class="food-section" data-section="gallery"><div class="food-section-head"><h2>From the studio</h2>'+link('View gallery →','gallery')+'</div><div class="food-gallery">'+d.gallery.slice(0,3).map((g,i)=>g.type==='video'?'<video controls playsinline src="'+esc(safe(g.url))+'"></video>':img(g.url,'Creative gallery '+(i+1),'gallery.'+i+'.url')).join('')+'</div></section>';case 'newsletter':return '<section class="food-newsletter" data-section="newsletter"><div><h2>'+txt(d,'newsletterTitle',o)+'</h2><p>'+txt(d,'newsletterText',o)+'</p></div><form data-form="newsletter"><input type="email" name="email" required aria-label="Email address" placeholder="Your email address"><button class="food-button">Subscribe</button><p class="food-status" role="status"></p></form></section>';default:return '';}}
function menuPage(d,route,o){const cat=d.categories.find(c=>c.id===route.split('/')[1]);return '<section class="food-section"><div class="food-breadcrumb">Home › Learning resources'+(cat?' › '+esc(cat.name):'')+'</div><h1 class="food-headline">'+esc(cat?.name||'Learning resources')+'</h1><p>'+esc(cat?.description||'Original work, limited editions and prints for your space.')+'</p><div class="food-filters">'+link('All','menu',cat?'':'active')+d.categories.filter(c=>c.visible!==false).map(c=>link(esc(c.name),'category/'+c.id,cat?.id===c.id?'active':'')).join('')+'</div><div class="food-search-row"><input id="food-search" type="search" placeholder="Search our collection" aria-label="Search resources"><select id="food-diet" aria-label="Collection filter"><option value="">All resources</option></select><select id="food-sort" aria-label="Sort resources"><option value="featured">Featured</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option></select></div><div id="food-menu-results">'+itemGrid(d,d.items.filter(p=>p.active&&(!cat||p.category===cat.id)),o)+'</div><p id="food-no-results" hidden>No matching items. Try another search.</p></section>';}
function itemPage(d,route,o){const p=d.items.find(p=>p.id===route.slice(5));if(!p||!p.active)return '<section class="food-section"><h1>Item unavailable</h1>'+link('Back to collection','menu')+'</section>';const i=d.items.indexOf(p);return '<section class="food-section"><div class="food-breadcrumb">'+link('← Back to collection','menu')+' › '+esc(p.name)+'</div><div class="food-item-detail"><div><div id="food-main-image">'+img(p.images[0],p.name,'items.'+i+'.images.0')+'</div><div class="food-thumbs">'+p.images.map((url,j)=>'<button data-gallery="'+j+'" aria-label="View image '+(j+1)+'">'+img(url,p.name)+'</button>').join('')+'</div>'+(p.video?'<video src="'+esc(safe(p.video))+'" controls playsinline></video>':'')+'</div><form id="food-item-form"><h1 class="food-headline">'+txt(d,'items.'+i+'.name',o)+'</h1><div class="food-price" id="food-item-price">'+money(p.onSale?p.salePrice:p.price)+'</div><p>'+txt(d,'items.'+i+'.description',o)+'</p><p>'+p.dietary.map(v=>'<span class="food-tag">'+esc(v)+'</span>').join(' ')+'</p>'+((p.sizes||[]).length?'<label>Size<select name="size">'+p.sizes.map((v,j)=>'<option value="'+j+'">'+esc(v.name)+' · '+money(v.price)+'</option>').join('')+'</select></label>':'')+((p.extras||[]).length?'<label>Extras</label>'+p.extras.slice(0,5).map((v,j)=>'<label class="food-check"><input type="checkbox" name="extra" value="'+j+'">'+esc(v.name)+' +'+money(v.price)+'</label>').join(''):'')+'<label>Quantity<input type="number" name="quantity" value="1" min="1" max="99" required></label><label>Special instructions<textarea name="notes" maxlength="500" placeholder="Personalisation, print or framing preferences?"></textarea></label><p class="food-muted">'+txt(d,'items.'+i+'.allergens',o)+' · Production '+esc(p.prep)+' days</p><button class="food-button" type="submit">Add to cart</button><p class="food-status" role="status"></p><details class="food-faq"><summary>Resource format & licence</summary><p>'+txt(d,'items.'+i+'.ingredients',o)+'</p></details></form></div></section>';}
const input=(name,label,type='text',extra='')=>'<label>'+esc(label)+'<input name="'+name+'" type="'+type+'" '+extra+'></label>';
function requestForm(d,kind){const identity=input('name','Full name','text','required minlength="2" maxlength="120"')+input('email','Email address','email','required maxlength="254"')+input('phone','Phone number','tel','required maxlength="40"');const hidden='<input name="website" tabindex="-1" autocomplete="off" aria-hidden="true" style="display:none">';if(kind==='reservations')return '<form data-form="reservation"><div class="food-form-grid">'+input('date','Preferred date','date','required min="'+new Date(Date.now()+d.bookingLead*86400000).toLocaleDateString('en-CA',{timeZone:'Africa/Johannesburg'})+'"')+'<label>Select a time<select name="time" required>'+d.reservationTimes.split(',').map(t=>'<option>'+esc(t.trim())+'</option>').join('')+'</select></label>'+input('guests','People attending','number','required min="1" max="'+Number(d.maxGuests)+'" value="2"')+'<label>Session type<select name="seating"><option>Select a service</option>'+d.services.map(s=>'<option>'+esc(s.name)+'</option>').join('')+'</select></label></div>'+identity+'<label>Your goals and questions<textarea name="notes" maxlength="1000"></textarea></label>'+hidden+'<button class="food-button">Request a session</button><p class="food-muted">Your session is a request until confirmed by the studio.</p><p class="food-status" role="status"></p></form>';if(kind==='catering')return '<form data-form="catering">'+identity+'<div class="food-form-grid">'+input('date','Event date','date','required min="'+new Date().toLocaleDateString('en-CA',{timeZone:'Africa/Johannesburg'})+'"')+input('guests','People attending','number','required min="1" max="5000"')+'</div><label>Package<select name="package">'+d.packages.map(p=>'<option>'+esc(p.name)+'</option>').join('')+'</select></label>'+input('budget','Budget per person (R)','number','min="0" max="100000"')+'<label>Dietary requirements<textarea name="dietary" maxlength="1000"></textarea></label><label>Event details<textarea name="notes" maxlength="1500" required></textarea></label>'+hidden+'<button class="food-button">Request a quote</button><p class="food-status" role="status"></p></form>';return '<form data-form="contact">'+identity+'<label>Your message<textarea name="notes" required maxlength="2000"></textarea></label>'+hidden+'<button class="food-button">Send enquiry</button><p class="food-status" role="status"></p></form>';}
function cartView(d,cart){return cart.map((line,index)=>{const p=d.items.find(p=>p.id===line.productId),v=p?variants(p)[line.variantIndex]:null;return {...line,index,p,v,price:Number(v?.price||0),available:!!p?.active&&!!v}});}
function cartPage(d,route,cart){const lines=cartView(d,cart),total=lines.reduce((a,l)=>a+l.price*l.quantity,0);if(!lines.length)return '<section class="food-section"><h1>Your cart</h1><div class="food-empty"><p>Your cart is empty.</p>'+link('Explore our collection','menu','food-button')+'</div></section>';const rows=lines.map(l=>'<article class="food-cart-row">'+img(l.p?.images[0],l.p?.name||'Unavailable')+'<div><h3>'+esc(l.p?.name||'Unavailable item')+'</h3><p class="food-muted">'+esc(l.v?.label||'Option no longer available')+'</p><p class="food-muted">'+esc(l.notes||'')+'</p><label>Quantity <input type="number" min="1" max="99" value="'+l.quantity+'" data-cart-quantity="'+l.index+'"></label><button data-remove="'+l.index+'">Remove</button></div><b>'+money(l.price*l.quantity)+'</b></article>').join('');const form='<form id="food-checkout-form"><h2>Checkout</h2><label>Order method<select name="fulfilment" required>'+[['deliveryEnabled','Delivery'],['collectionEnabled','Collection'],['dineInEnabled','Dine-in']].filter(([key])=>d[key]).map(([,v])=>'<option>'+v+'</option>').join('')+'</select></label>'+input('name','Full name','text','required minlength="2" maxlength="120"')+input('email','Email address','email','required maxlength="254"')+input('phone','Phone number','tel','required maxlength="40"')+input('address','Delivery address','text','maxlength="500"')+'<label>Preferred time<input name="time" type="time"></label><label>Order notes<textarea name="notes" maxlength="1000"></textarea></label><label>Payment method<select name="payment">'+d.paymentMethods.split(',').filter(Boolean).map(p=>'<option>'+esc(p.trim())+'</option>').join('')+'</select></label><div class="food-total"><span>Order total</span><b id="food-checkout-total">'+money(total)+'</b></div><p class="food-muted">Delivery: '+money(d.deliveryFee)+' when selected. Collection is free.</p><p class="food-muted">'+esc(d.checkoutText)+'</p><button class="food-button" '+(lines.some(l=>!l.available)?'disabled':'')+'>Place order</button><p class="food-status" role="status"></p></form>';return '<section class="food-section"><h1 class="food-headline">'+(route==='checkout'?'Checkout':'Your cart')+'</h1><div class="food-two"><div>'+rows+'<div class="food-total"><span>Items subtotal</span><b>'+money(total)+'</b></div>'+link('← Continue shopping','menu')+'</div><div class="food-box">'+(route==='checkout'?form:'<h2>Your order</h2><p>'+lines.reduce((a,l)=>a+l.quantity,0)+' items</p><div class="food-total"><span>Subtotal</span><b>'+money(total)+'</b></div><p class="food-muted">Delivery fees are added at checkout.</p>'+link('Continue to checkout →','checkout','food-button'))+'</div></div></section>';}
function pageBody(d,route,o,runtime){const education=educationPage(d,route,o,runtime);if(education!==null)return education;
if(route==='portfolio'||route.startsWith('portfolio/'))return portfolio(d,o,route.split('/')[1]||'');
if(route.startsWith('project/')){const i=d.projects.findIndex(p=>p.id===route.slice(8)&&p.visible);if(i<0)return '<section class="food-section"><h1>Project unavailable</h1></section>';const p=d.projects[i],key='projects.'+i;return '<section class="food-section">'+link('← All projects','portfolio')+'<h1 class="food-headline">'+txt(d,key+'.name',o)+'</h1>'+img(p.image,p.name,key+'.image')+'<div class="food-grid">'+['client','brief','process','deliverables'].map(k=>'<article><h3>'+esc(k[0].toUpperCase()+k.slice(1))+'</h3><p>'+txt(d,key+'.'+k,o)+'</p></article>').join('')+'</div>'+(p.video?'<video controls playsinline src="'+esc(safe(p.video))+'"></video>':'')+link('Start your project','commissions','food-button')+'</section>'}
if(route==='services')return coachingPage(d,o);
if(route==='commissions')return '<section class="food-section"><h1 class="food-headline">Let’s create something together</h1><p>Tell us your project type, creative brief, budget and deadline.</p>'+requestForm(d,'contact')+'</section>';
if(route==='testimonials')return '<section class="food-section"><h1 class="food-headline">Kind words</h1>'+d.testimonials.map((t,i)=>'<blockquote><p>'+txt(d,'testimonials.'+i+'.quote',o)+'</p><cite>'+txt(d,'testimonials.'+i+'.name',o)+'</cite></blockquote>').join('')+'</section>';
if(route==='journal'||route.startsWith('article/')){const articles=route==='journal'?d.journal:d.journal.filter((_,i)=>String(i)===route.slice(8));return '<section class="food-section"><h1 class="food-headline">Studio journal</h1><div class="food-grid">'+articles.map(j=>{const i=d.journal.indexOf(j);return '<article>'+img(j.image,j.title,'journal.'+i+'.image')+'<h2>'+link(txt(d,'journal.'+i+'.title',o),'article/'+i)+'</h2><p>'+txt(d,'journal.'+i+'.text',o)+'</p></article>'}).join('')+'</div></section>'}
if(route==='home')return d.sections.filter(id=>!d.hiddenSections.includes(id)).map(id=>homeSection(d,id,o)).join('');if(route==='menu'||route==='categories'||route.startsWith('category/'))return menuPage(d,route,o);if(route.startsWith('item/'))return itemPage(d,route,o);if(['cart','checkout'].includes(route))return cartPage(d,route,runtime.cart);if(route==='specials')return '<section class="food-section"><h1 class="food-headline">Our specials</h1></section>'+homeSection(d,'specials',o)+homeSection(d,'featured',o);if(route==='about')return '<section class="food-section"><h1 class="food-headline">Our story</h1></section>'+homeSection(d,'about',o);if(route==='gallery')return '<section class="food-section"><h1 class="food-headline">Studio gallery</h1><p>Photography, original art and thoughtful design.</p><div class="food-gallery">'+d.gallery.map((g,i)=>g.type==='video'?'<video controls playsinline preload="metadata" src="'+esc(safe(g.url))+'"></video>':img(g.url,'Gallery image '+(i+1),'gallery.'+i+'.url')).join('')+'</div></section>';if(route==='reservations')return '<section class="food-section"><h1 class="food-headline">Book coaching</h1><div class="food-two"><div>'+img(d.aboutImage,'Learning & coaching','aboutImage')+'<h2>Tell us about your next creative project.</h2><p class="food-muted">'+esc(d.hours).replace(/\n/g,'<br>')+'</p></div><div class="food-box">'+(d.reservationEnabled?requestForm(d,'reservations'):'<p>Online session requests are currently unavailable. Please contact us directly.</p>'+link('Contact us','contact'))+'</div></div></section>';if(route==='catering')return '<section class="food-section"><h1 class="food-headline">'+txt(d,'cateringTitle',o)+'</h1><p>'+txt(d,'cateringText',o)+'</p><div class="food-grid">'+d.packages.map((p,i)=>'<div class="food-box"><h3>'+txt(d,'packages.'+i+'.name',o)+'</h3><p>'+txt(d,'packages.'+i+'.description',o)+'</p><b>From '+money(p.price)+' pp</b></div>').join('')+'</div><div class="food-two" style="margin-top:30px"><div><h2>Tell us about your occasion.</h2>'+img(d.specialImage,'Catering menu','specialImage')+'</div><div class="food-box">'+requestForm(d,'catering')+'</div></div></section>';if(route==='contact')return '<section class="food-section"><h1 class="food-headline">Let’s get in touch</h1><div class="food-two"><div><h2>Let’s create together</h2><p>'+txt(d,'address',o)+'</p><p>'+txt(d,'email',o)+'</p><p>'+txt(d,'phone',o)+'</p><h3>Opening hours</h3><p>'+txt(d,'hours',o)+'</p>'+(d.address?'<a class="food-button secondary" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(d.address)+'">Get directions ↗</a>':'')+(d.whatsapp?'<p><a class="food-button secondary" target="_blank" rel="noopener" href="https://wa.me/'+esc(d.whatsapp.replace(/\D/g,''))+'">Chat on WhatsApp</a></p>':'')+'</div><div class="food-box">'+requestForm(d,'contact')+'</div></div></section>';if(route==='faq')return '<section class="food-section"><h1 class="food-headline">Questions? We’re here to help.</h1>'+d.faq.map((f,i)=>'<details class="food-faq"><summary>'+txt(d,'faq.'+i+'.question',o)+'</summary><p>'+txt(d,'faq.'+i+'.answer',o)+'</p></details>').join('')+'<div class="food-filters">'+['delivery','refunds','privacy','terms'].map(id=>link(id[0].toUpperCase()+id.slice(1),id)).join('')+'</div></section>';if(['delivery','refunds','privacy','terms'].includes(route))return '<section class="food-section"><h1 class="food-headline">'+esc(route[0].toUpperCase()+route.slice(1))+'</h1><p>'+txt(d,'policy'+route[0].toUpperCase()+route.slice(1),o)+'</p></section>';if(route==='orders')return '<section class="food-section"><h1 class="food-headline">My orders</h1><p class="food-muted">Orders placed on this device appear here. Refresh an order to check its current status.</p><div id="food-order-history">'+(runtime.history.length?runtime.history.map(order=>'<article class="food-box" style="margin:15px 0"><h3>'+esc(order.number)+'</h3><p>'+money(order.total)+' · '+esc(order.status||'Received')+' · Payment '+esc(order.paymentStatus||'pending')+'</p><button class="food-button secondary" data-track="'+esc(order.key)+'">Refresh status</button></article>').join(''):'<p>No orders yet.</p>'+link('Explore our collection','menu','food-button'))+'</div></section>';if(route==='confirmation'){const order=runtime.history[0];return '<section class="food-section"><div class="food-box"><small class="food-eyebrow">THANK YOU</small><h1 class="food-headline">Your order has been received.</h1><p>'+esc(order?.number||'')+'</p><p>Our team will confirm production, delivery and payment details.</p><div class="food-steps"><span>Received</span><span>Preparing</span><span>Ready</span><span>Completed</span></div><p>Total: '+money(order?.total)+'</p>'+link('Track my order','orders','food-button')+'</div></section>';}const custom=d.customPages.find(p=>p.id===route);return custom?'<section class="food-section"><h1 class="food-headline">'+esc(custom.title)+'</h1></section>':'<section class="food-section"><h1>Page not found</h1>'+link('Back home','home')+'</section>';}

function footer(d,o){return '<footer class="food-footer"><div><h2>'+txt(d,'brand',o)+'</h2><p>'+txt(d,'footer',o)+'</p></div><div><h3>Learn & grow</h3>'+link('Courses','courses')+link('Coaching','coaching')+link('Resources','menu')+link('Student dashboard','dashboard')+'</div><div><h3>Here to help</h3>'+link('About & coaches','about')+link('Contact','contact')+link('FAQs','faq')+link('Privacy','privacy')+link('Terms','terms')+link('Refunds & cancellations','refunds')+'</div><small>© '+new Date().getFullYear()+' '+esc(d.brand)+' · Hosted by SGC Network</small></footer>'}
function courseCard(d,c,o){const i=d.courses.indexOf(c);return '<article class="edu-course">'+link(img(c.image,c.name,'courses.'+i+'.image'),'course/'+c.id)+'<div><small class="edu-chip">'+esc(c.category)+'</small><h3>'+link(txt(d,'courses.'+i+'.name',o),'course/'+c.id)+'</h3><p>'+txt(d,'courses.'+i+'.description',o)+'</p><p class="food-muted">'+esc(c.level)+' · '+c.lessons.length+' lessons</p><b>'+money(c.price)+'</b>'+link('Explore course →','course/'+c.id,'edu-course-link')+'</div></article>'}
function courseCatalogue(d,o,category='',featured=false){const found=d.courses.filter(c=>c.active&&(!category||c.category===category)&&(!featured||c.featured));return '<section class="food-section"><div class="food-section-head"><h'+(featured?'2':'1')+' class="food-headline">'+(featured?'Courses for your next chapter':'All courses')+'</h'+(featured?'2':'1')+'>'+link('Browse courses →','courses')+'</div>'+(!featured?'<input id="edu-course-search" type="search" placeholder="Search courses" aria-label="Search courses"><div class="food-filters">'+link('All','courses')+d.courseCategories.map(c=>link(esc(c),'courses/'+encodeURIComponent(c),category===c?'active':'')).join('')+'</div>':'')+'<div class="food-grid" id="edu-course-results">'+found.map(c=>courseCard(d,c,o)).join('')+'</div></section>'}
function coachingPage(d,o){return '<section class="food-section"><h2 class="food-headline">Coaching for a brighter you</h2><p>Personal guidance to help you gain clarity, build confidence and create meaningful progress.</p><div class="food-grid">'+d.services.map((s,i)=>'<article class="food-box"><small class="edu-chip">'+esc(s.duration)+' minutes</small><h3>'+txt(d,'services.'+i+'.name',o)+'</h3><p>'+txt(d,'services.'+i+'.description',o)+'</p><p>'+money(s.price)+'</p>'+link('Book a session','reservations','food-button')+'</article>').join('')+'</div></section>'}
function membershipsPage(d,o){return '<section class="food-section"><h2 class="food-headline">Join '+esc(d.brand)+'</h2><p>Ongoing learning, practical resources and support for your next chapter.</p><div class="food-grid">'+d.plans.filter(p=>p.active).map((p,i)=>'<article class="edu-plan '+(i===1?'featured':'')+'">'+(i===1?'<small class="edu-chip">Most popular</small>':'')+'<h3>'+esc(p.name)+'</h3><strong>'+money(p.price)+'</strong><p>per month · manual renewal</p><p>'+esc(p.description)+'</p><ul>'+p.benefits.split('\n').map(b=>'<li>'+esc(b)+'</li>').join('')+'</ul>'+link('Choose '+esc(p.name),'join/'+p.id,'food-button')+'</article>').join('')+'</div></section>'}
function enrolKey(d,r,courseId){return r.history.find(h=>h.status==='Active'&&((h.kind==='enrolment'&&h.courseId===courseId)||(h.kind==='membership'&&h.courseIds?.includes(courseId)&&new Date(h.endsAt).getTime()>Date.now())))?.key||''}
function studentForm(d,kind,id,title,price){return '<section class="food-section"><div class="food-two"><div><small class="edu-chip">YOUR NEXT STEP</small><h1 class="food-headline">'+esc(title)+'</h1><p>Total '+money(price)+'</p><p>'+esc(d.checkoutText)+'</p></div><form class="food-box edu-purchase" data-kind="'+kind+'" data-id="'+esc(id)+'">'+input('name','Full name','text','required minlength="2" maxlength="120"')+input('email','Email address','email','required maxlength="254"')+input('phone','Phone number','tel','required maxlength="40"')+'<label>Payment method<select name="payment">'+d.paymentMethods.split(',').map(m=>'<option>'+esc(m.trim())+'</option>').join('')+'</select></label><label>Notes<textarea name="notes" maxlength="1000"></textarea></label><button class="food-button">Submit request</button><p class="food-status" role="status"></p></form></div></section>'}
function classroom(d,route,o,r){const [,id,raw]=route.split('/'),c=d.courses.find(c=>c.id===id&&c.active),index=Number(raw||0);if(!c||!c.lessons[index])return '<section class="food-section"><h1>Lesson unavailable</h1></section>';const key=enrolKey(d,r,id),data=o.preview?c.lessons[index]:(key?r.lessons[id+'/'+index]:null);return '<section class="food-section"><div class="edu-classroom"><aside><h2>'+esc(c.name)+'</h2>'+c.lessons.map((l,i)=>link((i+1)+'. '+esc(l.title),'lesson/'+id+'/'+i,index===i?'active':'')).join('')+link('Student dashboard','dashboard')+'</aside><div><div class="edu-lesson" data-course="'+esc(id)+'" data-index="'+index+'" data-access="'+esc(key)+'"><h1>'+esc(c.lessons[index].title)+'</h1>'+(data?lessonContents(data,id,index,o,r):'<div class="food-box"><p>'+(key?'Loading your lesson…':'This course unlocks after your payment is confirmed. Open your dashboard to refresh or restore your access.')+'</p>'+link('Open student dashboard','dashboard','food-button')+link('Enrol in this course','enrol/'+id,'food-button secondary')+'</div>')+'</div></div></div></section>'}
function lessonContents(l,id,index,o,r){return (l.video?'<video controls playsinline preload="metadata" src="'+esc(safe(l.video))+'"></video>':'<div class="edu-video-empty"><span>▶</span><p>Lesson video</p><small>The educator can upload a video or add a video URL.</small></div>')+'<p class="edu-lesson-body">'+esc(l.body||'').replace(/\n/g,'<br>')+'</p>'+(l.resource?'<p><a class="food-button secondary" href="'+esc(safe(l.resource))+'" target="_blank" rel="noopener">Download workbook ↗</a></p>':'')+'<h3>Reflect</h3><p>'+esc(l.reflection||'What will you put into practice?')+'</p><label>Your private notes<textarea id="edu-notes" maxlength="5000">'+esc(r.notes[id+'/'+index]||'')+'</textarea></label>'+((l.quiz||[]).length?'<form id="edu-quiz"><h3>Knowledge check</h3>'+l.quiz.map((q,i)=>'<fieldset><legend>'+esc(q.question)+'</legend>'+q.options.map((answer,j)=>'<label><input type="radio" required name="answer'+i+'" value="'+j+'"> '+esc(answer)+'</label>').join('')+'</fieldset>').join('')+'<button class="food-button">Submit answers & complete lesson</button></form>':'<button class="food-button" id="edu-complete">Complete lesson</button>')+'<p class="food-status" id="edu-lesson-status" role="status"></p><p>'+link('Next lesson →','lesson/'+id+'/'+(index+1))+'</p>'}
function educationPage(d,route,o,r){if(route==='courses'||route.startsWith('courses/'))return courseCatalogue(d,o,decodeURIComponent(route.split('/')[1]||''));if(route.startsWith('course/')){const c=d.courses.find(c=>c.id===route.slice(7)&&c.active);if(!c)return '<section class="food-section"><h1>Course unavailable</h1></section>';const i=d.courses.indexOf(c),k='courses.'+i;return '<section class="food-section"><div class="food-two"><div>'+img(c.image,c.name,k+'.image')+'</div><div><small class="edu-chip">'+esc(c.category)+' · '+esc(c.level)+'</small><h1 class="food-headline">'+txt(d,k+'.name',o)+'</h1><p>'+txt(d,k+'.description',o)+'</p><p>With '+txt(d,k+'.instructor',o)+'</p><h2>'+money(c.price)+'</h2>'+link('Enrol now','enrol/'+c.id,'food-button')+link('Open classroom','lesson/'+c.id+'/0','food-button secondary')+'</div></div><h2>What you will learn</h2><ul>'+c.outcomes.split('\n').map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><h2>Course curriculum</h2>'+c.lessons.map((l,j)=>'<details class="food-faq"><summary>'+esc(l.module)+' · '+esc(l.title)+'</summary><p>'+esc(l.duration)+' minutes</p>'+link('Open lesson','lesson/'+c.id+'/'+j)+'</details>').join('')+'</section>'}if(route.startsWith('lesson/'))return classroom(d,route,o,r);if(route==='testimonials')return '<section class="food-section"><h2 class="food-headline">Learner stories</h2>'+d.testimonials.map((t,i)=>'<blockquote><p>'+txt(d,'testimonials.'+i+'.quote',o)+'</p><cite>'+txt(d,'testimonials.'+i+'.name',o)+'</cite></blockquote>').join('')+'</section>';if(route==='coaching')return coachingPage(d,o);if(route==='memberships')return membershipsPage(d,o);if(route.startsWith('enrol/')){const c=d.courses.find(c=>c.id===route.slice(6)&&c.active);return c?studentForm(d,'enrolment',c.id,c.name,c.price):'<section class="food-section">Course unavailable</section>'}if(route.startsWith('join/')){const p=d.plans.find(p=>p.id===route.slice(5)&&p.active);return p?studentForm(d,'membership',p.id,p.name+' membership',p.price):'<section class="food-section">Plan unavailable</section>'}if(route==='events')return '<section class="food-section"><h1 class="food-headline">Events & workshops</h1><p>Live learning, meaningful conversations and practical next steps.</p><div class="food-grid">'+d.events.filter(e=>e.active).map(e=>'<article class="edu-course">'+img(e.image,e.name)+'<div><small class="edu-chip">'+esc(e.date)+' · '+esc(e.time)+'</small><h2>'+esc(e.name)+'</h2><p>'+esc(e.location)+'</p><p>'+esc(e.description)+'</p><b>'+money(e.price)+'</b>'+link('Register','event/'+e.id,'food-button')+'</div></article>').join('')+'</div></section>';if(route.startsWith('event/')){const e=d.events.find(e=>e.id===route.slice(6)&&e.active);return e?studentForm(d,'event',e.id,e.name,e.price):'<section class="food-section">Event unavailable</section>'}if(route==='about')return '<section class="food-section"><h1 class="food-headline">'+txt(d,'aboutTitle',o)+'</h1><p>'+txt(d,'about',o)+'</p><div class="food-grid">'+d.coaches.map((c,i)=>'<article class="edu-course">'+img(c.image,c.name,'coaches.'+i+'.image')+'<div><h2>'+txt(d,'coaches.'+i+'.name',o)+'</h2><p>'+txt(d,'coaches.'+i+'.role',o)+'</p><p>'+txt(d,'coaches.'+i+'.bio',o)+'</p><p>'+txt(d,'coaches.'+i+'.credentials',o)+'</p></div></article>').join('')+'</div></section>';if(['dashboard','certificates','library','billing'].includes(route))return dashboard(d,route,o,r);if(route==='signin')return '<section class="food-section"><h1 class="food-headline">Your learning workspace</h1><p>Your purchases and private access references are kept on this device. Restore a reference on the student dashboard to continue on another device.</p>'+link('Open student dashboard','dashboard','food-button')+'<p>Educators can <a href="https://sgcnetwork.co.za/signin.html">sign in to SGC</a> to manage their academy.</p></section>';return null;}
function dashboard(d,route,o,r){const courses=o.preview?d.courses:r.history.filter(h=>h.status==='Active').flatMap(h=>d.courses.filter(c=>h.courseId===c.id||h.courseIds?.includes(c.id))),unique=[...new Map(courses.map(c=>[c.id,c])).values()];return '<section class="food-section"><div class="edu-dashboard"><aside><h2>My learning</h2>'+[['dashboard','Dashboard'],['library','Purchased resources'],['certificates','Certificates'],['billing','Orders & billing']].map(([id,title])=>link(title,id,route===id?'active':'')).join('')+'</aside><div><h1 class="food-headline">'+(route==='library'?'Your resource library':route==='certificates'?'Your certificates':route==='billing'?'Orders & billing':'Welcome to your next chapter')+'</h1><div class="edu-stats"><div><b>'+unique.length+'</b>Courses</div><div><b>'+r.history.filter(h=>h.kind==='booking').length+'</b>Coaching requests</div><div><b>'+unique.filter(c=>c.lessons.every(l=>r.progress[c.id]?.[l.id])).length+'</b>Completed courses</div></div><button class="food-button secondary" id="edu-refresh">Refresh purchases & access</button><form id="edu-restore"><label>Restore your private access reference<input name="key" required placeholder="xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"></label><button class="food-button secondary">Restore access</button></form><p class="food-status" id="edu-dashboard-status"></p>'+(route==='library'?'<div id="edu-library"><p>Confirmed digital purchases appear here when you refresh your library.</p><button class="food-button" id="edu-library-refresh">Load purchased downloads</button></div>':route==='billing'?r.history.map(h=>'<article class="food-box"><h3>'+esc(h.title||h.number)+'</h3><p>'+esc(h.number)+' · '+esc(h.kind)+' · '+money(h.total)+'</p><p>'+esc(h.status)+' · Payment '+esc(h.paymentStatus||'pending')+'</p><details><summary>Private access reference</summary><code>'+esc(h.key)+'</code><p>Keep this private. It restores access on another device.</p></details></article>').join(''):'<div class="food-grid">'+unique.map(c=>{const count=c.lessons.filter(l=>r.progress[c.id]?.[l.id]).length,pct=Math.round(count/Math.max(1,c.lessons.length)*100);return '<article class="edu-course">'+img(c.image,c.name)+'<div><h2>'+esc(c.name)+'</h2><progress max="100" value="'+pct+'"></progress><p>'+pct+'% complete</p>'+(route==='certificates'?'<button class="food-button" data-certificate="'+esc(c.id)+'">View certificate</button>':link('Continue learning','lesson/'+c.id+'/'+Math.min(count,c.lessons.length-1),'food-button'))+'</div></article>'}).join('')+'</div>')+(r.history.length?'':'<div class="food-box"><p>Your confirmed courses, memberships and purchases will appear here.</p>'+link('Browse courses','courses','food-button')+'</div>')+'</div></div></section>'}
function bindEducation(host,d,route,o){const r=o.runtime,navigate=path=>o.navigate?o.navigate(path):location.hash=path,redraw=()=>render(host,d,route,o);const search=host.querySelector('#edu-course-search');if(search)search.oninput=()=>{const term=search.value.toLowerCase();host.querySelectorAll('.edu-course').forEach(el=>el.hidden=!el.textContent.toLowerCase().includes(term))};host.querySelectorAll('form.edu-purchase').forEach(form=>{let key=uid();form.onsubmit=async e=>{e.preventDefault();const status=form.querySelector('.food-status');if(o.preview){status.textContent='Preview only — no enrolment, booking or payment was submitted.';return}const button=form.querySelector('button');button.disabled=true;try{const result=await request({action:'submit',kind:form.dataset.kind,id:form.dataset.id,slug:o.slug,key,fields:Object.fromEntries(new FormData(form))});r.history.unshift({...result.record,key});r.save();navigate('billing')}catch(error){status.textContent=error.message}finally{button.disabled=false}}});
const lesson=host.querySelector('.edu-lesson');if(lesson){const id=lesson.dataset.course,index=Number(lesson.dataset.index),cache=id+'/'+index,key=lesson.dataset.access,notes=host.querySelector('#edu-notes');if(!o.preview&&key&&!r.lessons[cache]){request({action:'classroom',slug:o.slug,key,courseId:id,index}).then(data=>{r.lessons[cache]=data.lesson;r.progress[id]=data.progress||{};r.save();redraw()}).catch(e=>{lesson.querySelector('.food-box p').textContent=e.message})}if(notes)notes.oninput=()=>{r.notes[cache]=notes.value;r.save()};const complete=async answers=>{const status=host.querySelector('#edu-lesson-status');try{let result;if(o.preview){const l=d.courses.find(c=>c.id===id).lessons[index],correct=(l.quiz||[]).map((q,i)=>Number(answers?.[i])===Number(q.correct));result={passed:!correct.length||correct.every(Boolean),score:correct.length?Math.round(correct.filter(Boolean).length/correct.length*100):100,results:(l.quiz||[]).map((q,i)=>({question:q.question,yourAnswer:q.options[answers?.[i]]||'',correctAnswer:q.options[q.correct]}))};if(result.passed){r.progress[id]??={};r.progress[id][l.id]=true}}else result=await request({action:'complete',slug:o.slug,key,courseId:id,index,answers});if(result.progress)r.progress[id]=result.progress;r.save();status.replaceChildren();const message=document.createElement('p');message.textContent=(result.passed?'Lesson complete. ':'Review your answers and try again. ')+'Score '+result.score+'%';status.append(message);for(const q of result.results||[]){const p=document.createElement('p');p.textContent=q.question+' · Your answer: '+q.yourAnswer+' · Correct answer: '+q.correctAnswer;status.append(p)}const c=d.courses.find(c=>c.id===id);const next=host.querySelector('.edu-lesson>p:last-child a');if(next){next.href=index+1<c.lessons.length?'#lesson/'+id+'/'+(index+1):'#dashboard';next.textContent=index+1<c.lessons.length?'Next lesson →':'Back to dashboard →';next.onclick=e=>{e.preventDefault();navigate(next.getAttribute('href').slice(1))}}}catch(e){status.textContent=e.message}};const quiz=host.querySelector('#edu-quiz');if(quiz)quiz.onsubmit=e=>{e.preventDefault();complete(Array.from(new FormData(quiz).values()).map(Number))};const button=host.querySelector('#edu-complete');if(button)button.onclick=()=>complete([]);}
const dashboardStatus=host.querySelector('#edu-dashboard-status');async function refresh(key){if(o.preview){dashboardStatus.textContent='Preview workspace. No live records have been requested.';return}const data=await request({action:'track',slug:o.slug,key});const found=r.history.find(h=>h.key===key);if(found)Object.assign(found,data.record);else r.history.push({...data.record,key});if(data.record.progress)Object.assign(r.progress,data.record.progress);r.save();}const refreshButton=host.querySelector('#edu-refresh');if(refreshButton)refreshButton.onclick=async()=>{refreshButton.disabled=true;try{for(const h of r.history)await refresh(h.key);redraw()}catch(e){dashboardStatus.textContent=e.message}finally{refreshButton.disabled=false}};const restore=host.querySelector('#edu-restore');if(restore)restore.onsubmit=async e=>{e.preventDefault();try{await refresh(restore.elements.key.value.trim());redraw()}catch(e){dashboardStatus.textContent=e.message}};host.querySelectorAll('[data-certificate]').forEach(button=>button.onclick=async()=>{try{const id=button.dataset.certificate,c=d.courses.find(c=>c.id===id);let result;if(o.preview){if(!c.lessons.every(l=>r.progress[id]?.[l.id]))throw Error('Complete all lessons and required quizzes first.');result={name:'Preview learner',course:c.name,number:'PREVIEW',date:new Date().toLocaleDateString('en-ZA')}}else result=await request({action:'certificate',slug:o.slug,key:enrolKey(d,r,id),courseId:id});const panel=document.createElement('div');panel.className='edu-certificate';for(const value of ['Certificate of completion',result.name,result.course,result.date,result.number,'This confirms completion; it is not an accredited qualification.']){const p=document.createElement('p');p.textContent=value;panel.append(p)}const download=document.createElement('button');download.className='food-button secondary';download.textContent='Download certificate';download.onclick=()=>{const rows=['Certificate of completion',result.name,result.course,result.date,result.number,'Issued by '+d.brand,'Completion certificate — not an accredited qualification.'];const svg='<svg xmlns="http://www.w3.org/2000/svg" width="1120" height="790" viewBox="0 0 1120 790"><rect width="1120" height="790" fill="#fffaf3"/><rect x="30" y="30" width="1060" height="730" fill="none" stroke="#6520c5" stroke-width="4"/>'+rows.map((value,i)=>'<text x="560" y="'+(160+i*77)+'" text-anchor="middle" font-family="Georgia,serif" font-size="'+(i===0?42:i===1?34:i===6?16:24)+'" fill="#2c1054">'+esc(value)+'</text>').join('')+'</svg>';const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'})),a=document.createElement('a');a.href=url;a.download='completion-certificate.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)};panel.append(download);button.parentElement.append(panel)}catch(e){dashboardStatus.textContent=e.message}});const library=host.querySelector('#edu-library-refresh');if(library)library.onclick=async()=>{const area=host.querySelector('#edu-library');if(o.preview){area.textContent='Preview library. Paid downloads appear after order payment is confirmed.';return}try{const downloads=[];for(const h of r.history.filter(h=>h.kind==='order')){const data=await request({action:'library',slug:o.slug,key:h.key});downloads.push(...data.downloads)}area.replaceChildren();if(!downloads.length)area.textContent='No paid digital downloads yet.';for(const file of downloads){const a=document.createElement('a');a.className='food-button secondary';a.textContent=file.name+' ↗';a.href=safe(file.url);a.target='_blank';a.rel='noopener';area.append(a)}}catch(e){dashboardStatus.textContent=e.message}};}

function blocks(d,route,o){const p=d.pageContent[route];if(!p)return '';const linked=p.category?'<section class="food-section">'+itemGrid(d,d.items.filter(item=>item.active&&item.category===p.category),o)+'</section>':'';return linked+ '<section class="food-section food-custom"'+(p.background?' style="background:'+esc(p.background)+';color:'+esc(p.color||d.theme.ink)+'"':'')+'>'+p.blocks.map((b,i)=>{const key='pageContent.'+route+'.blocks.'+i;return '<div class="food-block" data-movable="block-'+esc(b.id)+'">'+(b.type==='image'?img(b.url,'Page image',key+'.url'):b.type==='video'?'<video src="'+esc(safe(b.url))+'" controls playsinline></video>':b.type==='button'?link(txt(d,key+'.text',o),b.target||'menu','food-button'):b.type==='heading'?'<h2>'+txt(d,key+'.text',o)+'</h2>':'<p>'+txt(d,key+'.text',o)+'</p>')+'</div>'}).join('')+'</section>';}
function runtime(slug='food-preview'){let stored={};try{stored=JSON.parse(localStorage.getItem('sgc-education-customer:'+slug)||'{}')}catch{}const state={cart:stored.cart||[],history:stored.history||[],checkoutKey:stored.checkoutKey||null,lessons:{},progress:stored.progress||{},notes:stored.notes||{},profile:stored.profile||{}};state.save=()=>{try{localStorage.setItem('sgc-education-customer:'+slug,JSON.stringify({cart:state.cart,history:state.history,checkoutKey:state.checkoutKey,progress:state.progress,notes:state.notes,profile:state.profile}))}catch{}};return state;}
function applyTheme(host,d){host.classList.add('food-site');for(const [key,val]of Object.entries(d.theme))if(['background','ink','accent','olive','soft'].includes(key))host.style.setProperty('--food-'+(key==='background'?'bg':key),/^#[\da-f]{6}$/i.test(val)?val:'#fffdf7');host.style.setProperty('--food-radius',Math.max(0,Math.min(40,Number(d.theme.radius)||0))+'px');host.style.setProperty('--food-heading',['Playfair Display','Georgia','Arial','DM Sans'].includes(d.theme.heading)?d.theme.heading:'Georgia');host.style.fontFamily=['DM Sans','Arial','Georgia','Playfair Display'].includes(d.theme.body)?'"'+d.theme.body+'"':'Arial';}
function render(host,raw,route='home',o={}){const d=normalize(raw),r=o.runtime||runtime(o.slug);applyTheme(host,d);for(const name of ['purple','teal','yellow'])host.style.setProperty('--edu-'+name,d.theme[name]);if(d.pageContent?.[route]){const pc=d.pageContent[route];host.style.setProperty('--food-bg',pc.background||d.theme.background);host.style.setProperty('--food-ink',pc.color||d.theme.ink)}host.innerHTML=header(d,o)+'<div class="food-content">'+pageBody(d,route,o,r)+blocks(d,route,o)+'</div>'+footer(d,o);applyElementChanges(host,d,route,o.device);bind(host,d,route,{...o,runtime:r});bindEducation(host,d,route,{...o,runtime:r});return host;}
function applyElementChanges(host,d,route,device){
 device=device||(innerWidth<650?'mobile':innerWidth<950?'tablet':'desktop');
 for(const [key,pos]of Object.entries(d.layout?.[device]||{})){if(!key.startsWith(route+'|'))continue;try{const el=host.querySelector(key.slice(route.length+1));if(el){el.style.position='relative';el.style.left=Number(pos.x||0)+'px';el.style.top=Number(pos.y||0)+'px';el.style.zIndex=pos.x||pos.y?'2':''}}catch{}}
 for(const [key,spec]of Object.entries(d.elementEdits?.[route]||{})){try{const el=host.querySelector(key);if(!el)continue;if(spec.text!==undefined&&!el.children.length)el.textContent=spec.text;if(spec.src&&['IMG','VIDEO'].includes(el.tagName))el.src=safe(spec.src);for(const k of ['color','backgroundColor','fontSize','textAlign','width','borderRadius','padding'])if(spec[k]!==undefined)el.style[k]=spec[k]}catch{}}
}
async function request(body){const res=await fetch('https://bxpexanyoyubxeqqlggh.supabase.co/functions/v1/education-business',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await res.json();if(!res.ok||data.error)throw Error(data.error||'Please try again later.');return data;}
function bind(host,d,route,o){const r=o.runtime,navigate=target=>{if(o.navigate)o.navigate(target);else location.hash=target;},redraw=()=>render(host,d,route,o),count=()=>host.querySelectorAll('[data-cart-count]').forEach(el=>el.textContent=r.cart.reduce((a,l)=>a+l.quantity,0));count();host.querySelectorAll('a[href^="#"]').forEach(a=>a.onclick=e=>{if(e.target.closest('[contenteditable=true]'))return;e.preventDefault();navigate(a.getAttribute('href').slice(1))});host.querySelectorAll('[data-key][contenteditable]').forEach(el=>{el.oninput=()=>o.onEdit?.(el.dataset.key,el.innerText);el.onpaste=e=>{e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'));}});host.querySelectorAll('[data-media]').forEach(el=>el.ondblclick=()=>o.onMedia?.(el.dataset.media));host.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>navigate('item/'+b.dataset.item));const results=host.querySelector('#food-menu-results');if(results){const cat=d.categories.find(c=>c.id===route.split('/')[1]);const update=()=>{const term=host.querySelector('#food-search').value.toLowerCase(),diet=host.querySelector('#food-diet').value,sort=host.querySelector('#food-sort').value;const items=d.items.filter(p=>p.active&&(!cat||p.category===cat.id)&&(!diet||p.dietary.includes(diet))&&(p.name+' '+p.description).toLowerCase().includes(term));if(sort==='low')items.sort((a,b)=>a.price-b.price);if(sort==='high')items.sort((a,b)=>b.price-a.price);results.innerHTML=itemGrid(d,items,o);host.querySelector('#food-no-results').hidden=items.length>0;results.querySelectorAll('a').forEach(a=>a.onclick=e=>{e.preventDefault();navigate(a.getAttribute('href').slice(1))});results.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>navigate('item/'+b.dataset.item));};['#food-search','#food-diet','#food-sort'].forEach(id=>host.querySelector(id).addEventListener('input',update));}
const itemForm=host.querySelector('#food-item-form');if(itemForm){const p=d.items.find(p=>p.id===route.slice(5)),vs=variants(p);const chosen=()=>{const size=Number(itemForm.elements.size?.value||0);let mask=0;itemForm.querySelectorAll('[name=extra]:checked').forEach(el=>mask|=1<<Number(el.value));return vs.findIndex(v=>v.size===size&&v.mask===mask)};itemForm.onchange=()=>{host.querySelector('#food-item-price').textContent=money(vs[chosen()].price)};itemForm.onsubmit=e=>{e.preventDefault();const vi=chosen(),qty=Number(itemForm.elements.quantity.value);if(!Number.isInteger(qty)||qty<1||qty>99)return;const existing=r.cart.find(l=>l.productId===p.id&&l.variantIndex===vi);if(existing){existing.quantity+=qty;existing.notes=[existing.notes,itemForm.elements.notes.value].filter(Boolean).join('; ')}else r.cart.push({productId:p.id,variantIndex:vi,quantity:qty,notes:itemForm.elements.notes.value});r.checkoutKey=null;r.save();count();itemForm.querySelector('.food-status').textContent='Added to your cart. Open Bag to continue.'};host.querySelectorAll('[data-gallery]').forEach(b=>b.onclick=()=>host.querySelector('#food-main-image').innerHTML=img(p.images[Number(b.dataset.gallery)],p.name));}
host.querySelectorAll('[data-cart-quantity]').forEach(el=>el.onchange=()=>{const qty=Number(el.value);if(!Number.isInteger(qty)||qty<1||qty>99)return; r.cart[Number(el.dataset.cartQuantity)].quantity=qty;r.checkoutKey=null;r.save();redraw()});host.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{r.cart.splice(Number(b.dataset.remove),1);r.checkoutKey=null;r.save();redraw()});const checkout=host.querySelector('#food-checkout-form');if(checkout){const updateTotal=()=>{host.querySelector('#food-checkout-total').textContent=money(cartView(d,r.cart).reduce((a,l)=>a+l.price*l.quantity,0)+(checkout.elements.fulfilment.value==='Delivery'?Number(d.deliveryFee||0):0))};checkout.elements.fulfilment.onchange=updateTotal;updateTotal();checkout.onsubmit=async e=>{e.preventDefault();const status=checkout.querySelector('.food-status');if(o.preview){status.textContent='Preview only — no real order or payment was submitted.';return}const fields=Object.fromEntries(new FormData(checkout));if(fields.fulfilment==='Delivery'&&!fields.address.trim()){status.textContent='Enter a delivery address.';return}const button=checkout.querySelector('button[type=submit],button.food-button');button.disabled=true;status.textContent='Sending your order…';r.checkoutKey??=uid();r.save();try{const result=await request({action:'submit',kind:'order',slug:o.slug,key:r.checkoutKey,fields,items:r.cart});r.history.unshift({...result.record,key:r.checkoutKey});r.cart=[];r.checkoutKey=null;r.save();navigate('confirmation')}catch(error){status.textContent=error.message}finally{button.disabled=false}};}
host.querySelectorAll('form[data-form]').forEach(form=>{let key=uid();form.onsubmit=async e=>{e.preventDefault();const status=form.querySelector('.food-status');if(o.preview){status.textContent='Preview only — this request has not been sent.';return}const button=form.querySelector('button');button.disabled=true;status.textContent='Sending…';try{const result=await request({action:'submit',kind:form.dataset.form,slug:o.slug,key,fields:Object.fromEntries(new FormData(form))});if(result.record){r.history.unshift({...result.record,key});r.save();}status.textContent=form.dataset.form==='reservation'?d.bookingConfirmation:'Thank you. Your request has been received.';form.reset();key=uid()}catch(error){status.textContent=error.message}finally{button.disabled=false}}});host.querySelectorAll('[data-track]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const result=await request({action:'track',slug:o.slug,key:b.dataset.track});const existing=r.history.find(x=>x.key===b.dataset.track);Object.assign(existing,result.record);r.save();redraw()}catch(error){b.textContent=error.message}finally{b.disabled=false}});
}
